mapper.select:
select tti.seq_no as seqNo, tti.sch_id as schId,
a.assetId as assetId, a.assetName as assetName, a.finprodType as finprodType, tti.asset_classify as assetClassify, tti.capi_income_feature as capiIncomeFeature, tti.income_type as incomeType, tti.taxable_sign as taxableSign, tti.tax_rate*100 as taxRate, DATE_FORMAT(tti.eff_date, '%Y-%m-%d') as effDate, tti.maintenance_mode as maintenanceMode, tti.fee_type as feeType from TAX_TAXABLE_INFO tti inner join (
select IFNULL(fp.finprod_market_id, fp.finprod_id) as assetId, IFNULL(fp.finprod_abbr, fp.finprod_name) as assetName, fp.finprod_type as finprodType, fp.finprod_id as originalFinprodId from fin_product_type fpt inner join fin_product fp on fp.finprod_id = fpt.finprod_id where fpt.type_3 is not null
union all
select ftp.finprod_id as assetId, ftp.finprod_id as assetName, ftp.finprod_type as finprodType, ftp.finprod_id as originalFinprodId from fin_product_type fpt inner join fin_trade_product ftp on ftp.finprod_id = fpt.finprod_id where fpt.type_3 is not null and ftp.branch = '0'
) a on a.originalFinprodId = tti.asset_id where tti.seq_no = #{seqNo,jdbcType=VARCHAR}

select * from (
select IFNULL(fp.finprod_market_id, fp.finprod_id) as assetId, IFNULL(fp.finprod_abbr, fp.finprod_name) as assetName, fp.capi_income_feature as capiIncomeFeature, fpt.type_3 as assetClassify, fp.finprod_type as finprodType, fp.finprod_id as originalFinprodId from fin_product_type fpt inner join fin_product fp on fp.finprod_id = fpt.finprod_id where fpt.type_3 is not null
union all
select ftp.finprod_id as assetId, ftp.finprod_id as assetName, ftp.capi_income_feature as capiIncomeFeature, fpt.type_3 as assetClassify, ftp.finprod_type as finprodType, ftp.finprod_id as originalFinprodId from fin_product_type fpt inner join fin_trade_product ftp on ftp.finprod_id = fpt.finprod_id where fpt.type_3 is not null and ftp.branch = '0'
)
where assetId = #{assetId} and finprodType = #{finprodType}
